quickStart.sql:
WITH durations AS (
  SELECT * FROM (VALUES (1.2), (0.7), (2.9), (1.8), (0.4), (3.6), (1.1), (2.2)) t(x)
), fit AS (
  SELECT dist_gamma_fit(x) AS f FROM durations
)
SELECT round(f.shape, 4) AS shape, round(f.scale, 4) AS scale,
       round(dist_gamma_ks_test(x, f.shape, f.scale).p_value, 4) AS ks_p_value
FROM durations, fit
GROUP BY f;
